def eulerian_num(n, k):
    """
    Calculate the Eulerian number A(n, k),
    which counts the number of permutations of {1,...,n}
    in which exactly k elements are greater than the previous element.

    Parameters:
    n (int): The size of the permutation (n >= 1).
    k (int): The number of ascents (0 <= k < n).

    Returns:
    int: The Eulerian number A(n, k).
    """
    if k < 0 or k >= n or n <= 0:
        return 0
    if n == 1:
        return 1 if k == 0 else 0

    # Use memoization to avoid recomputation
    memo = {}

    def A(n, k):
        if (n, k) in memo:
            return memo[(n, k)]
        if k < 0 or k >= n:
            return 0
        if n == 1:
            return 1 if k == 0 else 0
        val = (k + 1) * A(n - 1, k) + (n - k) * A(n - 1, k - 1)
        memo[(n, k)] = val
        return val

    return A(n, k)

