def answer(low, high):
    """
    Find and return one pair of positive integers (a, b) such that their LCM lies within [low, high].
    If no such pair exists, return None.
    """
    # A simple approach: try pairs (i, j) with i <= j in [1, high]
    # and check if their LCM is in the range.
    # To optimize, we try pairs with small i first.

    for a in range(1, high + 1):
        for b in range(a, high + 1):
            lcm = a * b // math.gcd(a, b)
            if low <= lcm <= high:
                return (a, b)
    return None

