def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # LIS (Strictly increasing) max sum ending at each index
    lis = arr[:]  # Initialize with the element itself
    for i in range(n):
        for j in range(i):
            if arr[j] < arr[i] and lis[j] + arr[i] > lis[i]:
                lis[i] = lis[j] + arr[i]

    # LDS (Strictly decreasing) max sum starting at each index
    lds = arr[:]  # Initialize with the element itself
    for i in range(n - 1, -1, -1):
        for j in range(n - 1, i, -1):
            if arr[j] < arr[i] and lds[j] + arr[i] > lds[i]:
                lds[i] = lds[j] + arr[i]

    max_sum_bitonic = 0
    for i in range(n):
        # Subtract arr[i] once because it is counted in both LIS and LDS
        current_sum = lis[i] + lds[i] - arr[i]
        if current_sum > max_sum_bitonic:
            max_sum_bitonic = current_sum

    return max_sum_bitonic

