        next_guess = (guess + n / guess) / 2
        if abs(next_guess - guess) < tolerance:
            return next_guess
        guess = next_guess
    return guess

def lps(s: str) -> str:
    n = len(s)
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = 1

    for length in range(2, n+1):
        for i in range(n-length+1):
            j = i + length - 1
            if s[i] == s[j]:
                dp[i][j] = 2 + (dp[i+1][j-1] if i+1 <= j-1 else 0)
            else:
                dp[i][j] = max(dp[i+1][j], dp[i][j-1])

    # Reconstruct the longest palindromic subsequence
    i, j = 0, n-1
    res = []
    while i <= j:
        if s[i] == s[j]:
            res.append(s[i])
            i += 1
            j -= 1
        elif dp[i+1][j] > dp[i][j-1]:
            i += 1
        else:
            j -= 1

    # res contains the first half (and middle if length is odd)
    # Construct the full palindrome
    half = ''.join(res)
    if dp[0][n-1] % 2 == 0:
        return half + half[::-1]
    else:
        return half + half[-2::-1]

