            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    total_sum = sum(arr)
    max_sub_sum = kadane(arr)

    if k == 1:
        return max_sub_sum

    # max prefix sum
    max_prefix = current = arr[0]
    for x in arr[1:]:
        current += x
        max_prefix = max(max_prefix, current)

    # max suffix sum
    max_suffix = current = arr[-1]
    for x in reversed(arr[:-1]):
        current += x
        max_suffix = max(max_suffix, current)

    if total_sum > 0:
        return max(max_sub_sum, max_suffix + total_sum * (k - 2) + max_prefix)
    else:
        return max(max_sub_sum, max_suffix + max_prefix)

