def otherside_rightangle(a, b):
    a, b = float(a), float(b)
    if a <= 0 or b <= 0:
        raise ValueError("Side lengths must be positive numbers.")
    # If one side is longer, it might be the hypotenuse
    if a > b:
        # Try a as hypotenuse, b as leg
        c_sq = a**2 - b**2
        if c_sq > 0:
            return math.sqrt(c_sq)
        else:
            # Otherwise, assume b is hypotenuse
            return math.sqrt(b**2 - a**2)
    elif b > a:
        # Try b as hypotenuse, a as leg
        c_sq = b**2 - a**2
        if c_sq > 0:
            return math.sqrt(c_sq)
        else:
            # Otherwise, assume a is hypotenuse
            return math.sqrt(a**2 - b**2)
    else:
        # a == b, so if both are equal, the third side can be leg or hypotenuse
        # If both are legs, third side is hypotenuse
        # If both are hypotenuse, third side is zero (not possible)
        # So assume both are legs:
        return math.sqrt(a**2 + b**2)

