    if n == -1:
        # All bits are set (considering two's complement for infinite bits),
        # no unset bit to set.
        return n

    bit_length = n.bit_length()
    # If n is 0, bit_length is 0, consider at least 1 bit
    if bit_length == 0:
        bit_length = 1

    for i in range(bit_length - 1, -1, -1):
        if not (n & (1 << i)):
            return n | (1 << i)
    # If all bits are set in existing bit length, set the next higher bit
    return n | (1 << bit_length)

