        raise ValueError("Input must be a non-negative integer")
    if n == 0:
        return 2
    elif n == 1:
        return 1
    a, b = 2, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

def convert_list_dictionary(lst):
    if not lst:
        return {}
    if len(lst) == 1:
        return lst[0]
    return {lst[0]: convert_list_dictionary(lst[1:])}

def get_max_sum(n, memo={}):
    if n == 0:
        return 0
    if n in memo:
        return memo[n]
    val = get_max_sum(n // 2, memo) + get_max_sum(n // 3, memo) + get_max_sum(n // 4, memo) + get_max_sum(n // 5, memo)
    memo[n] = max(val, n)
    return memo[n]

def first_non_repeating_character(s: str) -> str:
    from collections import Counter
    counts = Counter(s)
    for char in s:
        if counts[char] == 1:
            return char
    return ''

