def bitwise_xor(*tuples):
    if not tuples:
        return ()
    length = len(tuples[0])
    for t in tuples:
        if len(t) != length:
            raise ValueError("All tuples must be of the same length")
    result = []
    for i in range(length):
        xor_val = 0
        for t in tuples:
            xor_val ^= t[i]
        result.append(xor_val)
    return tuple(result)

def extract_freq(tuples):
    freq = {}
    for t in tuples:
        key = tuple(sorted(t))
        freq[key] = freq.get(key, 0) + 1
    return freq

def add_nested_tuples(*nested_tuples):
    # Find the maximum length among the nested tuples
    max_len = max(len(t) for t in nested_tuples)

    # Initialize the result list
    result = []

    for i in range(max_len):
        # Sum the elements at index i from each tuple, treating missing elements as 0
        s = 0
        for t in nested_tuples:
            if i < len(t):
                s += t[i]
            else:
                s += 0
        result.append(s)

    return tuple(result)

def ncr_modp(n, r, p):
    if r > n:
        return 0
    if r == 0 or r == n:
        return 1

    numerator = 1
    denominator = 1
    for i in range(r):
        numerator = (numerator * (n - i)) % p
        denominator = (denominator * (i + 1)) % p

    # Fermat's little theorem for modular inverse since p is prime
    def modinv(a, p):
        return pow(a, p - 2, p)

    return (numerator * modinv(denominator, p)) % p

import re

def is_valid_URL(url: str) -> bool:
    pattern = re.compile(
        r'^(https?)://'                        # scheme http or https
        r'(([A-Za-z0-9-]+\.)+[A-Za-z]{2,6})'  # domain
        r'(:\d{1,5})?'                        # optional port
        r'(/[\w\-.~:/?#[\]@!$&\'()*+,;=%]*)?$'  # optional path and query
    )
    return bool(pattern.match(url))

import heapq

def k_smallest_pairs(nums1, nums2, k):
    if not nums1 or not nums2 or k == 0:
        return []

    min_heap = []
    result = []

    # Initialize the heap with the first element in nums2 paired with each element in nums1
    for i in range(min(k, len(nums1))):
        heapq.heappush(min_heap, (nums1[i] + nums2[0], i, 0))

    while min_heap and len(result) < k:
        current_sum, i, j = heapq.heappop(min_heap)
        result.append([nums1[i], nums2[j]])
        if j + 1 < len(nums2):
            heapq.heappush(min_heap, (nums1[i] + nums2[j+1], i, j+1))

    return result

def min_product_tuple(tuples):
    min_product = None
    n = len(tuples)
    for i in range(n):
        for j in range(i + 1, n):
            a, b = tuples[i]
            c, d = tuples[j]
            product = a * b * c * d
            if min_product is None or product < min_product:
                min_product = product
    return min_product

