def get_maxgold(mine):
    if not mine or not mine[0]:
        return 0
    rows, cols = len(mine), len(mine[0])
    dp = [[0]*cols for _ in range(rows)]

    for col in range(cols-1, -1, -1):
        for row in range(rows):
            right = dp[row][col+1] if col+1 < cols else 0
            right_up = dp[row-1][col+1] if row-1 >= 0 and col+1 < cols else 0
            right_down = dp[row+1][col+1] if row+1 < rows and col+1 < cols else 0

            dp[row][col] = mine[row][col] + max(right, right_up, right_down)

    return max(dp[row][0] for row in range(rows))

