        return ()
    min_length = min(len(t) for t in tuples)
    result = []
    for i in range(min_length):
        product = 1
        for t in tuples:
            product *= t[i]
        result.append(product)
    return tuple(result)

def cal_sum(n):
    if n <= 0:
        return 0
    if n == 1:
        return 3  # P(0) = 3
    if n == 2:
        return 3 + 0  # P(0) + P(1)

    perrin = [3, 0, 2]
    total = sum(perrin[:min(n, 3)])

    for i in range(3, n):
        next_val = perrin[i-2] + perrin[i-3]
        perrin.append(next_val)
        total += next_val

    return total

