def find_peak(nums):
    n = len(nums)
    if n == 0:
        return None
    if n == 1:
        return 0

    left, right = 0, n - 1
    while left <= right:
        mid = (left + right) // 2

        left_val = nums[mid - 1] if mid - 1 >= 0 else float('-inf')
        right_val = nums[mid + 1] if mid + 1 < n else float('-inf')

        if nums[mid] >= left_val and nums[mid] >= right_val:
            return mid
        elif nums[mid] < right_val:
            left = mid + 1
        else:
            right = mid - 1
    return None

def max_product(nums):
    if not nums:
        return 0

    n = len(nums)
    dp = nums[:]  # dp[i] will store max product of increasing subsequence ending with nums[i]

    for i in range(n):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] * nums[i])

    return max(dp)

def max_profit(prices):
    profit = 0
    for i in range(1, len(prices)):
        if prices[i] > prices[i - 1]:
            profit += prices[i] - prices[i - 1]
    return profit

def tuple_intersection(tuple_list):
    if not tuple_list:
        return ()
    common = set(tuple_list[0])
    for t in tuple_list[1:]:
        common &= set(t)
    return tuple(common)
